// Keep focus on the composer through an overlay-click dismiss (symbiot#236). Clicking the
// Radix backdrop otherwise blurs the textarea to <body> as the mousedown's default action;
// that focus loss is the sole route-specific difference vs the reliable Cancel/Escape routes
// (which hold focus on a dialog descendant), and it is what leaves the eager highlight's
// rollback unreconciled on the blurred read-only editor under CI load. preventDefault stops
// only the focus shift — Radix still dismisses via its document-level pointerdown listener.
const keepFocusOnOverlayPress = useCallback((event: MouseEvent): void => {
  event.preventDefault();
}, []);

input.new_string:
// Make the overlay-click dismiss mirror the reliable Cancel-button route (symbiot#236). The
// eager-highlight rollback survives ONLY on the overlay route because that route runs onCancel
// from Radix's native pointerdown listener, while Cancel/Escape run it inside a React synthetic
// event where slate-react reconciles the blurred read-only editor. So: suppress Radix's native
// outside-dismiss (onPointerDownOutside preventDefault) and instead dismiss from a React onClick
// on the backdrop, and keep the mousedown from blurring the textarea to <body>. The overlay then
// matches the Cancel button in both event origin and focus.
const suppressNativeOutsideDismiss = useCallback((event: Event): void => {
  event.preventDefault();
}, []);
const keepFocusOnOverlayPress = useCallback((event: MouseEvent): void => {
  event.preventDefault();
}, []);
const dismissFromOverlayClick = useCallback((): void => {
  onCancel();
}, [onCancel]);

  className="sm:max-w-2xl"
  onPointerDownOutside={suppressNativeOutsideDismiss}
  overlayProps={{ onMouseDown: keepFocusOnOverlayPress, onClick: dismissFromOverlayClick }}
>

